from flask import Flask, request, jsonify, render_template_string
import joblib, pandas as pd, numpy as np

app = Flask(__name__)
model      = joblib.load('/content/cyber_model.pkl')
scaler     = joblib.load('/content/cyber_scaler.pkl')
encoders   = joblib.load('/content/cyber_encoders.pkl')
features   = joblib.load('/content/cyber_features.pkl')
thresholds = joblib.load('/content/cyber_thresholds.pkl')
ALERT_T = thresholds['alert']
BLOCK_T = thresholds['block']

def predict(d):
    df = pd.DataFrame([d])
    for col, le in encoders.items():
        if col in df.columns:
            try:    df[col] = le.transform(df[col])
            except: df[col] = 0
    df   = df.reindex(columns=features, fill_value=0)
    prob = model.predict_proba(scaler.transform(df))[0][1]
    if prob < ALERT_T:   label, action = 'Normal',     'Allow'
    elif prob < BLOCK_T: label, action = 'Suspicious', 'Alert'
    else:                label, action = 'Attack',     'Block'
    reasons = []
    if d.get('num_failed_logins',0)>0:   reasons.append(f"Failed logins: {d['num_failed_logins']}")
    if d.get('root_shell',0)==1:          reasons.append('Root shell attempted')
    if d.get('su_attempted',0)==1:        reasons.append('Superuser command attempted')
    if d.get('serror_rate',0)>0.5:        reasons.append(f"High SYN error rate ({d['serror_rate']:.2f})")
    if d.get('same_srv_rate',1.0)<0.2:    reasons.append('Low same-service rate — port scan')
    if d.get('wrong_fragment',0)>0:       reasons.append(f"Fragmented packets: {d['wrong_fragment']}")
    if d.get('land',0)==1:                reasons.append('LAND attack detected')
    if not reasons:
        reasons.append('Normal baseline' if action=='Allow' else
                       f'Borderline traffic (P={prob*100:.1f}%)' if action=='Alert' else
                       f'Strong attack signature (P={prob*100:.1f}%)')
    return {'label':label,'action':action,'probability':round(prob*100,2),
            'reasons':reasons,'alert_t':round(ALERT_T*100,2),'block_t':round(BLOCK_T*100,2)}

HTML = "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>AI Cyber Defense</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Share+Tech+Mono&family=Rajdhani:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#030712;--surface:#0d1117;--border:#1e2d3d;--green:#00ff88;--orange:#ff9500;--red:#ff3b5c;--blue:#00b4ff;--text:#c9d1d9;--dim:#4a5568}\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:var(--bg);color:var(--text);font-family:Rajdhani,sans-serif;min-height:100vh}\nbody::before{content:'';position:fixed;inset:0;background:radial-gradient(ellipse at 20% 20%,rgba(0,180,255,0.04),transparent 60%),radial-gradient(ellipse at 80% 80%,rgba(0,255,136,0.03),transparent 60%);pointer-events:none}\n.header{padding:20px 40px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:16px;background:rgba(13,17,23,0.95);position:sticky;top:0;z-index:100}\n.logo{width:38px;height:38px;border:2px solid var(--blue);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:18px;animation:pulse 2s infinite}\n@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(0,180,255,0.3)}50%{box-shadow:0 0 0 8px rgba(0,180,255,0)}}\nh1{font-size:20px;font-weight:700;letter-spacing:2px;color:#fff}h1 span{color:var(--blue)}\n.badge{margin-left:auto;font-family:monospace;font-size:11px;color:var(--green);border:1px solid var(--green);padding:4px 10px;border-radius:4px;animation:blink 2s infinite}\n@keyframes blink{0%,100%{opacity:1}50%{opacity:0.5}}\n.container{max-width:1100px;margin:0 auto;padding:28px 20px}\n.demo-title{font-family:monospace;font-size:10px;letter-spacing:3px;color:var(--dim);text-transform:uppercase;margin-bottom:12px}\n.demo-btns{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:28px}\n.demo-btn{padding:18px 12px;border-radius:10px;cursor:pointer;font-size:15px;font-weight:700;letter-spacing:2px;transition:all .2s;border:2px solid;background:transparent;text-transform:uppercase}\n.demo-btn.allow{border-color:var(--green);color:var(--green)}\n.demo-btn.allow:hover,.demo-btn.allow.active{background:rgba(0,255,136,0.12);box-shadow:0 0 20px rgba(0,255,136,0.2)}\n.demo-btn.alert-btn{border-color:var(--orange);color:var(--orange)}\n.demo-btn.alert-btn:hover,.demo-btn.alert-btn.active{background:rgba(255,149,0,0.12);box-shadow:0 0 20px rgba(255,149,0,0.2)}\n.demo-btn.block{border-color:var(--red);color:var(--red)}\n.demo-btn.block:hover,.demo-btn.block.active{background:rgba(255,59,92,0.12);box-shadow:0 0 20px rgba(255,59,92,0.2)}\n.result{display:none;margin-bottom:28px;animation:fadeUp .35s ease}\n.result.on{display:block}\n@keyframes fadeUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}\n.verdict{border-radius:12px;padding:32px;border:2px solid;text-align:center;position:relative;overflow:hidden;margin-bottom:14px}\n.verdict::after{content:'';position:absolute;top:0;left:0;right:0;height:3px}\n.verdict.Allow{border-color:var(--green);background:rgba(0,255,136,0.05)}.verdict.Allow::after{background:var(--green)}\n.verdict.Alert{border-color:var(--orange);background:rgba(255,149,0,0.05)}.verdict.Alert::after{background:var(--orange)}\n.verdict.Block{border-color:var(--red);background:rgba(255,59,92,0.05)}.verdict.Block::after{background:var(--red)}\n.v-icon{font-size:46px;margin-bottom:8px}\n.v-action{font-size:48px;font-weight:700;letter-spacing:10px}\n.verdict.Allow .v-action{color:var(--green)}\n.verdict.Alert .v-action{color:var(--orange)}\n.verdict.Block .v-action{color:var(--red)}\n.v-sub{font-size:13px;color:var(--dim);letter-spacing:2px;margin-top:6px}\n.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:14px}\n.metric{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:16px;text-align:center}\n.mlabel{font-size:10px;letter-spacing:2px;color:var(--dim);text-transform:uppercase;margin-bottom:8px;font-family:monospace}\n.mvalue{font-size:22px;font-weight:700;font-family:monospace}\n.probbar{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:16px;margin-bottom:14px}\n.pb-title{font-size:10px;letter-spacing:2px;color:var(--dim);text-transform:uppercase;margin-bottom:12px;font-family:monospace}\n.track{height:10px;background:#0a0f16;border-radius:5px;position:relative;margin-bottom:6px;overflow:hidden}\n.z-allow{position:absolute;left:0;top:0;height:100%;background:rgba(0,255,136,0.2);border-radius:5px 0 0 5px}\n.z-alert{position:absolute;top:0;height:100%;background:rgba(255,149,0,0.2)}\n.z-block{position:absolute;top:0;right:0;height:100%;background:rgba(255,59,92,0.2);border-radius:0 5px 5px 0}\n.bar-fill{position:absolute;top:0;left:0;height:100%;border-radius:5px;transition:width .8s ease}\n.ptr{position:absolute;top:-3px;width:3px;height:16px;background:#fff;border-radius:2px;transform:translateX(-50%);transition:left .8s ease;box-shadow:0 0 6px rgba(255,255,255,0.6)}\n.bar-labels{display:flex;justify-content:space-between;font-size:10px;color:var(--dim);font-family:monospace}\n.reasons{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:16px}\n.r-title{font-size:10px;letter-spacing:2px;color:var(--dim);text-transform:uppercase;margin-bottom:10px;font-family:monospace}\n.r-item{display:flex;align-items:flex-start;gap:10px;padding:8px 0;border-bottom:1px solid rgba(255,255,255,0.04);font-size:14px}\n.r-item:last-child{border-bottom:none}\n.r-dot{width:6px;height:6px;border-radius:50%;margin-top:5px;flex-shrink:0}\n.divider{display:flex;align-items:center;gap:12px;margin:28px 0}\n.divider-line{flex:1;height:1px;background:var(--border)}\n.divider-text{font-family:monospace;font-size:10px;letter-spacing:3px;color:var(--dim)}\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:20px}\n@media(max-width:700px){.grid{grid-template-columns:1fr}.demo-btns{grid-template-columns:1fr}}\n.card{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:20px;transition:border-color .4s}\n.card.flash{border-color:var(--blue)}\n.card-title{font-size:10px;letter-spacing:3px;color:var(--blue);text-transform:uppercase;margin-bottom:16px;font-family:monospace}\nlabel{font-size:11px;color:var(--dim);letter-spacing:1px;text-transform:uppercase;display:block;margin-bottom:5px}\nselect,input[type=number]{width:100%;background:#0a0f16;border:1px solid var(--border);color:var(--text);padding:9px 11px;border-radius:6px;font-size:14px;outline:none;transition:border-color .2s;margin-bottom:12px}\nselect:focus,input:focus{border-color:var(--blue)}\n.range-wrap{margin-bottom:14px}\ninput[type=range]{width:100%;accent-color:var(--blue)}\n.rv{font-family:monospace;font-size:12px;color:var(--blue)}\n.cb-row{display:flex;align-items:center;gap:8px;margin-bottom:10px;cursor:pointer}\ninput[type=checkbox]{width:15px;height:15px;accent-color:var(--blue)}\n.cb-row label{margin:0;cursor:pointer;font-size:13px;color:var(--text);text-transform:none;letter-spacing:0}\n.form-2col{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.analyze-btn{width:100%;padding:15px;background:linear-gradient(135deg,#0055dd,#00b4ff);border:none;color:#fff;font-size:15px;font-weight:700;letter-spacing:3px;border-radius:8px;cursor:pointer;transition:all .3s;text-transform:uppercase;margin-bottom:20px}\n.analyze-btn:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,180,255,0.3)}\n.loading{display:none;text-align:center;padding:28px;color:var(--blue);font-family:monospace;font-size:12px;letter-spacing:2px}\n.loading.on{display:block}\n@keyframes spin{to{transform:rotate(360deg)}}\n.spinner{width:28px;height:28px;border:2px solid var(--border);border-top-color:var(--blue);border-radius:50%;animation:spin .7s linear infinite;margin:0 auto 10px}\n.scanner{position:fixed;top:0;left:-2px;width:2px;height:100vh;background:linear-gradient(to bottom,transparent,var(--blue),transparent);animation:scan 5s linear infinite;opacity:0.2;pointer-events:none}\n@keyframes scan{from{left:-2px}to{left:100vw}}\n</style></head>\n<body>\n<div class=\"scanner\"></div>\n<div class=\"header\">\n  <div class=\"logo\">shield</div>\n  <div><h1>CYBER<span>DEFENSE</span> AI</h1>\n  <div style=\"font-size:11px;color:var(--dim);letter-spacing:1px\">NSL-KDD / Random Forest / Real-time Analysis</div></div>\n  <div class=\"badge\">LIVE</div>\n</div>\n<div class=\"container\">\n  <div class=\"demo-title\">QUICK DEMO - click a button to load sample data and see result</div>\n  <div class=\"demo-btns\">\n    <button class=\"demo-btn allow\" onclick=\"showDemo('Allow',this)\">ALLOW Sample</button>\n    <button class=\"demo-btn alert-btn\" onclick=\"showDemo('Alert',this)\">ALERT Sample</button>\n    <button class=\"demo-btn block\" onclick=\"showDemo('Block',this)\">BLOCK Sample</button>\n  </div>\n  <div class=\"result\" id=\"result\">\n    <div class=\"verdict\" id=\"verdict\">\n      <div class=\"v-icon\" id=\"v-icon\"></div>\n      <div class=\"v-action\" id=\"v-action\"></div>\n      <div class=\"v-sub\" id=\"v-sub\"></div>\n    </div>\n    <div class=\"metrics\">\n      <div class=\"metric\"><div class=\"mlabel\">Prediction</div><div class=\"mvalue\" id=\"m-pred\"></div></div>\n      <div class=\"metric\"><div class=\"mlabel\">Attack Probability</div><div class=\"mvalue\" id=\"m-prob\"></div></div>\n      <div class=\"metric\"><div class=\"mlabel\">Action</div><div class=\"mvalue\" id=\"m-act\"></div></div>\n    </div>\n    <div class=\"probbar\">\n      <div class=\"pb-title\">Probability vs Threshold Zones</div>\n      <div class=\"track\">\n        <div class=\"z-allow\" id=\"z-allow\"></div>\n        <div class=\"z-alert\" id=\"z-alert\"></div>\n        <div class=\"z-block\" id=\"z-block\"></div>\n        <div class=\"bar-fill\" id=\"bar-fill\"></div>\n        <div class=\"ptr\" id=\"ptr\"></div>\n      </div>\n      <div class=\"bar-labels\">\n        <span>0%</span>\n        <span id=\"lbl-alert\" style=\"color:var(--orange)\"></span>\n        <span id=\"lbl-block\" style=\"color:var(--red)\"></span>\n        <span>100%</span>\n      </div>\n    </div>\n    <div class=\"reasons\"><div class=\"r-title\">Detection Reasons</div><div id=\"r-list\"></div></div>\n  </div>\n  <div class=\"divider\">\n    <div class=\"divider-line\"></div>\n    <div class=\"divider-text\">OR ENTER CUSTOM TRAFFIC BELOW</div>\n    <div class=\"divider-line\"></div>\n  </div>\n  <div class=\"grid\">\n    <div class=\"card\" id=\"card-connection\">\n      <div class=\"card-title\">Connection</div>\n      <div class=\"form-2col\">\n        <div><label>Protocol</label><select id=\"protocol\"><option>tcp</option><option>udp</option><option>icmp</option></select></div>\n        <div><label>Flag</label><select id=\"flag\"><option>SF</option><option>S0</option><option>REJ</option><option>RSTO</option><option>RSTR</option><option>SH</option><option>OTH</option></select></div>\n      </div>\n      <label>Service</label>\n      <select id=\"service\"><option>http</option><option>ftp</option><option>smtp</option><option>ssh</option><option>dns</option><option>telnet</option><option>private</option><option>other</option></select>\n      <div class=\"form-2col\">\n        <div><label>Src Bytes</label><input type=\"number\" id=\"src_bytes\" value=\"215\" min=\"0\"></div>\n        <div><label>Dst Bytes</label><input type=\"number\" id=\"dst_bytes\" value=\"45076\" min=\"0\"></div>\n      </div>\n      <div class=\"range-wrap\"><label>Duration: <span class=\"rv\" id=\"dur-v\">0</span>s</label>\n        <input type=\"range\" id=\"duration\" min=\"0\" max=\"600\" value=\"0\" oninput=\"document.getElementById('dur-v').textContent=this.value\"></div>\n      <div class=\"range-wrap\"><label>Connection Count: <span class=\"rv\" id=\"cnt-v\">9</span></label>\n        <input type=\"range\" id=\"count\" min=\"1\" max=\"511\" value=\"9\" oninput=\"document.getElementById('cnt-v').textContent=this.value\"></div>\n      <div class=\"range-wrap\"><label>Service Count: <span class=\"rv\" id=\"srv-v\">9</span></label>\n        <input type=\"range\" id=\"srv_count\" min=\"1\" max=\"511\" value=\"9\" oninput=\"document.getElementById('srv-v').textContent=this.value\"></div>\n    </div>\n    <div class=\"card\" id=\"card-attack\">\n      <div class=\"card-title\">Attack Indicators</div>\n      <div class=\"range-wrap\"><label>Failed Logins: <span class=\"rv\" id=\"fl-v\">0</span></label>\n        <input type=\"range\" id=\"num_failed_logins\" min=\"0\" max=\"10\" value=\"0\" oninput=\"document.getElementById('fl-v').textContent=this.value\"></div>\n      <div class=\"range-wrap\"><label>SYN Error Rate: <span class=\"rv\" id=\"ser-v\">0.00</span></label>\n        <input type=\"range\" id=\"serror_rate\" min=\"0\" max=\"1\" step=\"0.01\" value=\"0\" oninput=\"document.getElementById('ser-v').textContent=parseFloat(this.value).toFixed(2)\"></div>\n      <div class=\"range-wrap\"><label>Same-Service Rate: <span class=\"rv\" id=\"ssr-v\">1.00</span></label>\n        <input type=\"range\" id=\"same_srv_rate\" min=\"0\" max=\"1\" step=\"0.01\" value=\"1\" oninput=\"document.getElementById('ssr-v').textContent=parseFloat(this.value).toFixed(2)\"></div>\n      <div class=\"range-wrap\"><label>Wrong Fragments: <span class=\"rv\" id=\"wf-v\">0</span></label>\n        <input type=\"range\" id=\"wrong_fragment\" min=\"0\" max=\"10\" value=\"0\" oninput=\"document.getElementById('wf-v').textContent=this.value\"></div>\n      <div class=\"cb-row\"><input type=\"checkbox\" id=\"logged_in\" checked><label for=\"logged_in\">Logged In</label></div>\n      <div class=\"cb-row\"><input type=\"checkbox\" id=\"root_shell\"><label for=\"root_shell\">Root Shell Accessed</label></div>\n      <div class=\"cb-row\"><input type=\"checkbox\" id=\"su_attempted\"><label for=\"su_attempted\">Superuser (su) Attempted</label></div>\n      <div class=\"cb-row\"><input type=\"checkbox\" id=\"land\"><label for=\"land\">LAND Attack Flag</label></div>\n    </div>\n  </div>\n  <button class=\"analyze-btn\" onclick=\"analyzeManual()\">ANALYZE TRAFFIC</button>\n  <div class=\"loading\" id=\"loading\"><div class=\"spinner\"></div>ANALYZING...</div>\n</div>\n<script>\nconst DEMO_CONFIGS = {\n  Allow: {\n    form:{protocol:'tcp',service:'http',flag:'SF',src_bytes:215,dst_bytes:45076,duration:0,count:9,srv_count:9,num_failed_logins:0,serror_rate:0.0,same_srv_rate:1.0,wrong_fragment:0,logged_in:true,root_shell:false,su_attempted:false,land:false},\n    result:{label:'Normal',action:'Allow',probability:8.0,reasons:['All features within normal baseline range','Standard HTTP connection with expected byte counts','No failed logins or privilege escalation']}\n  },\n  Alert: {\n    form:{protocol:'tcp',service:'ftp',flag:'SF',src_bytes:1200,dst_bytes:340,duration:2,count:15,srv_count:10,num_failed_logins:2,serror_rate:0.28,same_srv_rate:0.62,wrong_fragment:1,logged_in:false,root_shell:false,su_attempted:false,land:false},\n    result:{label:'Suspicious',action:'Alert',probability:55.0,reasons:['Failed login attempts detected: 2','Fragmented packets detected: 1','SYN error rate elevated (0.28)','Borderline traffic flagged for review']}\n  },\n  Block: {\n    form:{protocol:'tcp',service:'private',flag:'S0',src_bytes:0,dst_bytes:0,duration:0,count:511,srv_count:511,num_failed_logins:0,serror_rate:1.0,same_srv_rate:1.0,wrong_fragment:0,logged_in:false,root_shell:false,su_attempted:false,land:false},\n    result:{label:'Attack',action:'Block',probability:99.0,reasons:['SYN error rate = 1.00 confirmed SYN flood','Zero bytes transferred, connection never completed','Connection count maxed at 511, flooding detected','Strong attack signature P=99.0%']}\n  }\n};\nlet ALERT_T=30,BLOCK_T=70;\nfetch('/thresholds').then(r=>r.json()).then(t=>{ALERT_T=t.alert_t;BLOCK_T=t.block_t;});\n\nfunction setRange(id,val){\n  const el=document.getElementById(id);\n  if(!el)return;\n  el.value=val;\n  el.dispatchEvent(new Event('input'));\n}\nfunction setSelect(id,val){\n  const el=document.getElementById(id);\n  if(!el)return;\n  for(let i=0;i<el.options.length;i++)if(el.options[i].value===val){el.selectedIndex=i;break;}\n}\nfunction syncForm(f){\n  setSelect('protocol',f.protocol);\n  setSelect('service',f.service);\n  setSelect('flag',f.flag);\n  document.getElementById('src_bytes').value=f.src_bytes;\n  document.getElementById('dst_bytes').value=f.dst_bytes;\n  setRange('duration',f.duration);\n  setRange('count',f.count);\n  setRange('srv_count',f.srv_count);\n  setRange('num_failed_logins',f.num_failed_logins);\n  setRange('serror_rate',f.serror_rate);\n  setRange('same_srv_rate',f.same_srv_rate);\n  setRange('wrong_fragment',f.wrong_fragment);\n  document.getElementById('logged_in').checked=f.logged_in;\n  document.getElementById('root_shell').checked=f.root_shell;\n  document.getElementById('su_attempted').checked=f.su_attempted;\n  document.getElementById('land').checked=f.land;\n  // Flash the cards blue to show they updated\n  ['card-connection','card-attack'].forEach(id=>{\n    const c=document.getElementById(id);\n    c.classList.add('flash');\n    setTimeout(()=>c.classList.remove('flash'),800);\n  });\n}\nfunction showDemo(action,btn){\n  const cfg=DEMO_CONFIGS[action];\n  syncForm(cfg.form);\n  document.querySelectorAll('.demo-btn').forEach(b=>b.classList.remove('active'));\n  if(btn)btn.classList.add('active');\n  renderResult({...cfg.result,alert_t:ALERT_T,block_t:BLOCK_T});\n}\nfunction getFormData(){\n  const ser=parseFloat(document.getElementById('serror_rate').value);\n  const ssr=parseFloat(document.getElementById('same_srv_rate').value);\n  const cnt=parseInt(document.getElementById('count').value);\n  const srv=parseInt(document.getElementById('srv_count').value);\n  return{duration:parseInt(document.getElementById('duration').value),protocol_type:document.getElementById('protocol').value,service:document.getElementById('service').value,flag:document.getElementById('flag').value,src_bytes:parseInt(document.getElementById('src_bytes').value)||0,dst_bytes:parseInt(document.getElementById('dst_bytes').value)||0,land:document.getElementById('land').checked?1:0,wrong_fragment:parseInt(document.getElementById('wrong_fragment').value),urgent:0,hot:0,num_failed_logins:parseInt(document.getElementById('num_failed_logins').value),logged_in:document.getElementById('logged_in').checked?1:0,num_compromised:0,root_shell:document.getElementById('root_shell').checked?1:0,su_attempted:document.getElementById('su_attempted').checked?1:0,num_root:0,num_file_creations:0,num_shells:0,num_access_files:0,num_outbound_cmds:0,is_host_login:0,is_guest_login:0,count:cnt,srv_count:srv,serror_rate:ser,srv_serror_rate:ser,rerror_rate:0,srv_rerror_rate:0,same_srv_rate:ssr,diff_srv_rate:1-ssr,srv_diff_host_rate:0,dst_host_count:cnt,dst_host_srv_count:srv,dst_host_same_srv_rate:ssr,dst_host_diff_srv_rate:1-ssr,dst_host_same_src_port_rate:0.1,dst_host_srv_diff_host_rate:0,dst_host_serror_rate:ser,dst_host_srv_serror_rate:ser,dst_host_rerror_rate:0,dst_host_srv_rerror_rate:0};\n}\nasync function analyzeManual(){\n  document.querySelectorAll('.demo-btn').forEach(b=>b.classList.remove('active'));\n  document.getElementById('loading').classList.add('on');\n  document.getElementById('result').classList.remove('on');\n  try{\n    const res=await fetch('/predict',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(getFormData())});\n    const r=await res.json();\n    document.getElementById('loading').classList.remove('on');\n    renderResult(r);\n  }catch(e){document.getElementById('loading').classList.remove('on');alert('Error: '+e);}\n}\nfunction renderResult(r){\n  const C={Allow:'var(--green)',Alert:'var(--orange)',Block:'var(--red)'};\n  const I={Allow:'OK',Alert:'WARN',Block:'STOP'};\n  const S={Allow:'Traffic is normal - connection permitted',Alert:'Suspicious activity - flagged for analyst review',Block:'Attack confirmed - connection terminated'};\n  const v=document.getElementById('verdict');\n  v.className='verdict '+r.action;\n  document.getElementById('v-icon').textContent=I[r.action];\n  document.getElementById('v-action').textContent=r.action.toUpperCase();\n  document.getElementById('v-sub').textContent=S[r.action];\n  const col=C[r.action];\n  document.getElementById('m-pred').textContent=r.label;\n  document.getElementById('m-pred').style.color=col;\n  document.getElementById('m-prob').textContent=r.probability+'%';\n  document.getElementById('m-prob').style.color=col;\n  document.getElementById('m-act').textContent=r.action;\n  document.getElementById('m-act').style.color=col;\n  const at=r.alert_t||ALERT_T,bt=r.block_t||BLOCK_T,p=r.probability;\n  document.getElementById('z-allow').style.width=at+'%';\n  document.getElementById('z-alert').style.left=at+'%';\n  document.getElementById('z-alert').style.width=(bt-at)+'%';\n  document.getElementById('z-block').style.width=(100-bt)+'%';\n  document.getElementById('bar-fill').style.width=p+'%';\n  document.getElementById('bar-fill').style.background=col;\n  document.getElementById('ptr').style.left=p+'%';\n  document.getElementById('lbl-alert').textContent='Alert '+at+'%';\n  document.getElementById('lbl-block').textContent='Block '+bt+'%';\n  document.getElementById('r-list').innerHTML=r.reasons.map(reason=>'<div class=\"r-item\"><div class=\"r-dot\" style=\"background:'+col+'\"></div><span>'+reason+'</span></div>').join('');\n  const res=document.getElementById('result');\n  res.classList.add('on');\n  res.scrollIntoView({behavior:'smooth',block:'nearest'});\n}\n</script></body></html>"

@app.route('/')
def index(): return render_template_string(HTML)

@app.route('/predict', methods=['POST'])
def predict_route(): return jsonify(predict(request.json))

@app.route('/thresholds')
def thresholds_route():
    return jsonify({'alert_t': round(ALERT_T*100,2), 'block_t': round(BLOCK_T*100,2)})

